from scipy.integrate import solve_ivp
from nominal import beam
def timegate(L,C,Vg):
 b=beam(dict(length_mm=L,width_mm=10,substrate_mm=.15,piezo_layer_mm=.12,tip_mass_g=4.65,damping_ratio=.015))
 m,c,k,th,cp,M=b['m'],b['c'],b['k'],b['theta'],b['cp'],b['forcing_mass']; Cs=C*1e-6
 def rhs(t,y):
  x,xv,v,vs=y; ih=max((abs(v)-max(vs,0)-.3)/5000,0); il=np.sign(v)*ih
  return [xv,(-c*xv-k*x-th*v-M*.15*9.81*np.sin(2*np.pi*45*t))/m,(th*xv-il)/cp,(ih-vs/1e7-200e-9)/Cs]
 sol=solve_ivp(rhs,[0,30],[0,0,0,0],max_step=1e-4,rtol=1e-7,atol=[1e-9,1e-6,1e-6,1e-8],dense_output=True)
 ts=np.linspace(0,30,6000); vs=sol.sol(ts)[3]; idx=np.where(vs>=Vg)[0]
 return (ts[idx[0]] if len(idx) else None, vs[-1])
for L in [29.8,30,30.3,30.6,31]:
 for C,Vg in [(80,3.1),(100,2.9),(120,2.9)]: print(L,C,Vg,timegate(L,C,Vg))
 print()
", "reason": "Compare final cold-start timing for plausible effective main lengths."}

